import{_ as e,g as a,e as n,a4 as i}from"./chunks/framework.CEYJDsBW.js";const b=JSON.parse('{"title":"GiantAnvilEvent","description":"","frontmatter":{},"headers":[],"relativePath":"en/anvilcraft/26.1/events/giant-anvil-event.md","filePath":"en/anvilcraft/26.1/events/giant-anvil-event.md"}'),c={name:"en/anvilcraft/26.1/events/giant-anvil-event.md"};function l(r,t,o,d,v,s){return a(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="giantanvilevent" tabindex="-1">GiantAnvilEvent <a class="header-anchor" href="#giantanvilevent" aria-label="Permalink to &quot;GiantAnvilEvent&quot;">​</a></h1><p>To forbid only a specific multiblock crafting attempt, cancel <code>Multiblock</code>. It is posted after the giant anvil has landed and right as the built-in listener is about to look up the crafting table array, causing only that crafting logic to return. <code>getLanding()</code> provides the original landing event, from which you can read the level, landing position, and entity.</p><p><code>BlockTick</code> is posted at the entry of the giant anvil block&#39;s server scheduled tick; canceling skips that block tick. <code>FallingTick</code> is posted at the very start of the falling giant anvil entity&#39;s <code>tick</code>; canceling skips that entity tick, including timing and movement—let subsequent ticks pass when motion should resume. Subscribe to the three static subtypes; the outer <code>GiantAnvilEvent</code> is a container class. <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/event/giantanvil/GiantAnvilLandingEventListener.java" target="_blank" rel="noreferrer">Multiblock processing entrypoint</a> · <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/entity/FallingGiantAnvilEntity.java" target="_blank" rel="noreferrer">Entity tick</a></p><table tabindex="0"><thead><tr><th>Event Type</th><th>Construction Site</th></tr></thead><tbody><tr><td><code>GiantAnvilEvent</code></td><td>No direct construction call site under this name in this commit</td></tr><tr><td><code>GiantAnvilEvent.Multiblock</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/event/giantanvil/GiantAnvilLandingEventListener.java#L28" target="_blank" rel="noreferrer"><code>GiantAnvilLandingEventListener:28</code></a></td></tr><tr><td><code>GiantAnvilEvent.BlockTick</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/workstation/GiantAnvilBlock.java#L318" target="_blank" rel="noreferrer"><code>GiantAnvilBlock:318</code></a></td></tr><tr><td><code>GiantAnvilEvent.FallingTick</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/entity/FallingGiantAnvilEntity.java#L82" target="_blank" rel="noreferrer"><code>FallingGiantAnvilEntity:82</code></a></td></tr></tbody></table>',4)])])}const f=e(c,[["render",l]]);export{b as __pageData,f as default};
